insert into purchase_results select lives_ok($$select public.save_admin_purchase_draft(null,' Fornecedor ','2026-09-03',' Nota ', '[{"product_id":"de620000-0000-4000-8000-000000000001","quantity":"2.000","unit_cost":"4.50"},{"product_id":"de620000-0000-4000-8000-000000000002","quantity":"3.500","unit_cost":"2.00"}]')$$,'draft with active and inactive products saved');
insert into purchase_results select is((select count(*) from public.stock_movements where source_type='purchase'),0::bigint,'draft does not change stock');
insert into purchase_results select is((select total_amount from public.purchases where supplier_name='Fornecedor'),16::numeric,'total recalculated from items');
insert into purchase_results select is((select count(*) from public.purchase_items),2::bigint,'multiple items persisted');
insert into purchase_results select throws_ok($$select public.save_admin_purchase_draft(null,null,'2026-09-03',null,'[{"product_id":"de620000-0000-4000-8000-000000000001","quantity":1,"unit_cost":1},{"product_id":"de620000-0000-4000-8000-000000000001","quantity":2,"unit_cost":1}]')$$,'22023','purchase_item_invalid','duplicate product rejected');
insert into purchase_results select throws_ok($$select public.save_admin_purchase_draft(null,null,'2026-09-03',null,'[{"product_id":"de620000-0000-4000-8000-000000000003","quantity":1,"unit_cost":1}]')$$,'42501','purchase_unauthorized','cross tenant rejected');
insert into purchase_results select throws_ok($$select public.save_admin_purchase_draft(null,null,'2026-09-03',null,'[{"product_id":"de620000-0000-4000-8000-000000000001","quantity":0,"unit_cost":1}]')$$,'22023','purchase_item_invalid','zero quantity rejected');
insert into purchase_results select throws_ok($$select public.save_admin_purchase_draft(null,null,'2026-09-03',null,'[{"product_id":"de620000-0000-4000-8000-000000000001","quantity":1,"unit_cost":-1}]')$$,'22023','purchase_item_invalid','negative cost rejected');
insert into purchase_results select lives_ok($$select public.confirm_admin_purchase((select id from public.purchases where supplier_name='Fornecedor'))$$,'confirmation succeeds');
insert into purchase_results select is((select count(*) from public.stock_movements where source_type='purchase'),2::bigint,'one movement per item');
insert into purchase_results select is((select movement_type||':'||source_type||':'||quantity_delta::text||':'||unit_cost::text from public.stock_movements where product_id='de620000-0000-4000-8000-000000000001'),'purchase:purchase:2.000:4.50','ledger preserves purchase origin positive delta and cost');
insert into purchase_results select ok((select status='confirmed' and confirmed_at is not null from public.purchases where supplier_name='Fornecedor'),'confirmation updates status and timestamp');
insert into purchase_results select throws_ok($$select public.confirm_admin_purchase((select id from public.purchases where supplier_name='Fornecedor'))$$,'55000','purchase_already_confirmed','double confirmation rejected');
insert into purchase_results select is((select count(*) from public.stock_movements where source_type='purchase'),2::bigint,'double confirmation does not duplicate stock');
insert into purchase_results select throws_ok($$update public.purchase_items set quantity=9 where product_id='de620000-0000-4000-8000-000000000001'$$,'55000','purchase_confirmed_read_only','confirmed items immutable');
insert into purchase_results select is((select count(*) from public.purchases),0::bigint,'management false hides purchases');
insert into purchase_results select throws_ok($$select public.save_admin_purchase_draft(null,null,'2026-09-03',null,'[{"product_id":"de620000-0000-4000-8000-000000000001","quantity":1,"unit_cost":1}]')$$,'42501','purchase_unauthorized','management false blocks writes');
insert into purchase_results select throws_ok($$select * from public.purchases$$,'42501',null,'anon cannot read purchases');
insert into purchase_results select ok(not has_table_privilege('service_role','public.purchases','SELECT,INSERT,UPDATE,DELETE'),'service role receives no purchase grants');
insert into purchase_results select * from finish(); select result from purchase_results; rollback;
