begin;
create extension if not exists pgtap with schema extensions;
create temp table purchase_results(result text); grant select,insert on purchase_results to authenticated,anon;
update public.business_modules set enabled=true where module='management' and business_id in ('be620000-0000-4000-8000-000000000001','be620000-0000-4000-8000-000000000002');

set local role authenticated; select set_config('request.jwt.claims','{"sub":"ae620000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update public.business_modules set enabled=false where business_id='be620000-0000-4000-8000-000000000001' and module='management';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"ae620000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role; set local role anon;
reset role;
